   100→export const action = async ({ request }: ActionFunctionArgs) => {
   101→  try {
   102→    const { session, admin } = await authenticate.admin(request);
   103→    const shop = session.shop;
   104→    const formData = await request.formData();
   105→    const intent = formData.get("intent");
   106→
   107→    if (intent === "save") {
   108→      const data = {
   109→        position: String(formData.get("position") || "inline"),
   110→        primaryColor: String(formData.get("primaryColor") || "#008060"),
   111→        successColor: String(formData.get("successColor") || "#008060"),
   112→        errorColor: String(formData.get("errorColor") || "#D72C0D"),
   113→        backgroundColor: String(formData.get("backgroundColor") || "#FFFFFF"),
   114→        textColor: String(formData.get("textColor") || "#202223"),
   115→        heading: String(formData.get("heading") || "Check Delivery Availability"),
   116→        placeholder: String(formData.get("placeholder") || "Enter your zip code"),
   117→        buttonText: String(formData.get("buttonText") || "Check"),
   118→        successMessage: String(
   119→          formData.get("successMessage") ||
   120→            "Great news! We deliver to your area.",
   121→        ),
   122→        errorMessage: String(
   123→          formData.get("errorMessage") ||
   124→            "Sorry, we don't deliver to this area yet.",
   125→        ),
   126→        notFoundMessage: String(
   127→          formData.get("notFoundMessage") ||
   128→            "We currently do not ship to this ZIP code.",
   129→        ),
   130→        showEta: formData.get("showEta") === "true",
   131→        showZone: formData.get("showZone") === "true",
   132→        showWaitlistOnFailure: formData.get("showWaitlistOnFailure") === "true",
   133→        showCod: formData.get("showCod") === "true",
   134→        showReturnPolicy: formData.get("showReturnPolicy") === "true",
   135→        showCutoffTime: formData.get("showCutoffTime") === "true",
   136→        showDeliveryDays: formData.get("showDeliveryDays") === "true",
   137→        showDeliveryDate: formData.get("showDeliveryDate") === "true",
   138→        showCountdown: formData.get("showCountdown") === "true",
   139→        showDeliveryFee: formData.get("showDeliveryFee") === "true",
   140→        blockCartOnInvalid: formData.get("blockCartOnInvalid") === "true",
   141→        blockCheckoutInCart: formData.get("blockCheckoutInCart") === "true",
   142→        showSocialProof: formData.get("showSocialProof") === "true",
   143→        borderRadius: String(formData.get("borderRadius") || "8"),
   144→        customCss: String(formData.get("customCss") || "") || null,
   145→      };
   146→
   147→      // Server-side plan gating: strip premium fields the shop's plan doesn't allow
   148→      const subscription = await getShopSubscription(shop);
   149→      const limits = PLAN_LIMITS[subscription.planTier];
   150→      if (!limits.widgetFullCustom) {
   151→        data.primaryColor = "#008060";
   152→        data.successColor = "#008060";
   153→        data.errorColor = "#D72C0D";
   154→        data.backgroundColor = "#FFFFFF";
   155→        data.textColor = "#202223";
   156→        data.position = "inline";
   157→      }
   158→      if (!limits.showEtaCodReturn) {
   159→        data.showEta = false;
   160→        data.showZone = false;
   161→        data.showCod = false;
   162→        data.showReturnPolicy = false;
   163→        data.showCutoffTime = false;
   164→        data.showDeliveryDays = false;
   165→        data.showDeliveryDate = false;
   166→        data.showCountdown = false;
   167→        data.showDeliveryFee = false;
   168→      }
   169→      if (!limits.customCss) {
   170→        data.customCss = null;
   171→      }
   172→      if (!limits.cartBlocking) {
   173→        data.blockCartOnInvalid = false;
   174→        data.blockCheckoutInCart = false;
   175→      }
   176→
   177→      await db.widgetConfig.upsert({
   178→        where: { shop },
   179→        create: { shop, ...data },
   180→        update: data,
   181→      });
   182→
   183→      await syncConfigMetafield(admin, data);
   184→
   185→      return { success: true };
   186→    }
   187→
   188→    if (intent === "reset") {
   189→      const resetData = {
   190→        position: "inline",
   191→        primaryColor: "#008060",
   192→        successColor: "#008060",
   193→        errorColor: "#D72C0D",
   194→        backgroundColor: "#FFFFFF",
   195→        textColor: "#202223",
   196→        heading: "Check Delivery Availability",
   197→        placeholder: "Enter your zip code",
   198→        buttonText: "Check",
   199→        successMessage: "Great news! We deliver to your area.",
   200→        errorMessage: "Sorry, we don't deliver to this area yet.",
   201→        notFoundMessage: "We currently do not ship to this ZIP code.",
   202→        showEta: true,
   203→        showZone: false,
   204→        showWaitlistOnFailure: false,
   205→        showCod: true,
   206→        showReturnPolicy: true,
   207→        showCutoffTime: true,
   208→        showDeliveryDays: true,
   209→        showDeliveryDate: true,
   210→        showCountdown: true,
   211→        showDeliveryFee: true,
   212→        blockCartOnInvalid: false,
   213→        blockCheckoutInCart: false,
   214→        showSocialProof: true,
   215→        borderRadius: "8",
   216→        customCss: null,
   217→      };
   218→
   219→      await db.widgetConfig.upsert({
   220→        where: { shop },
   221→        create: { shop },
   222→        update: resetData,
   223→      });
   224→
   225→      await syncConfigMetafield(admin, resetData);
   226→
   227→      return { success: true, action: "reset" };
   228→    }
   229→
   230→    return null;
   231→  } catch {
   232→    return new Response(JSON.stringify({ error: "Failed to save widget settings." }), {
   233→      status: 500,
   234→      headers: { "Content-Type": "application/json" },
   235→    });
   236→  }
   237→};
