   334→  // ── Delivery date formatter ───────────────────────────────────────────────────
   335→  function formatDeliveryDate(isoDate) {
   336→    if (!isoDate) return null;
   337→    try {
   338→      var parts = isoDate.split('-');
   339→      var d = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
   340→      var days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
   341→      var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
   342→      return days[d.getDay()] + ', ' + months[d.getMonth()] + ' ' + d.getDate();
   343→    } catch(e) { return null; }
   344→  }
