// ── Lock ATC buttons until ZIP check (floating/popup mode only) ────────────
// Disables Add to Cart and Buy Now buttons on page load. They stay disabled
// until the customer successfully validates their ZIP via the widget.
// Re-enabled by a zcc:validated event with valid=true, which is fired by wireWidget.
function lockAtcButtonsForZipCheck() {
  var ATC_SELECTORS = [
    'button[name="add"]',
    '.product-form__submit',
    '[data-product-add]',
    '.btn--add-to-cart',
    '.product-form button[type="submit"]',
    'button.shopify-payment-button__button',
    '.shopify-payment-button button',
    'button.product-form__cart-submit',
    'button[data-testid="Checkout-button"]',
    'form[action*="/cart/add"] button[type="submit"]'
  ].join(',');

  function applyLock() {
    try {
      var btns = document.querySelectorAll(ATC_SELECTORS);
      btns.forEach(function(b) {
        if (!b.closest('[data-zcc-widget]')) {
          if (!b.getAttribute('data-zcc-zip-locked')) {
            b.setAttribute('data-zcc-zip-orig-title', b.title || '');
            b.setAttribute('data-zcc-zip-orig-opacity', b.style.opacity || '');
            b.setAttribute('data-zcc-zip-orig-cursor', b.style.cursor || '');
          }
          b.disabled = true;
          b.style.opacity = '0.5';
          b.style.cursor = 'not-allowed';
          b.title = 'Please verify your ZIP code first';
          b.setAttribute('data-zcc-zip-locked', 'true');
        }
      });
    } catch(e) {}
  }

  function removeLock() {
    try {
      var btns = document.querySelectorAll('[data-zcc-zip-locked]');
      btns.forEach(function(b) {
        b.disabled = false;
        b.style.opacity = b.getAttribute('data-zcc-zip-orig-opacity') || '';
        b.style.cursor = b.getAttribute('data-zcc-zip-orig-cursor') || '';
        b.title = b.getAttribute('data-zcc-zip-orig-title') || '';
        b.removeAttribute('data-zcc-zip-locked');
        b.removeAttribute('data-zcc-zip-orig-title');
        b.removeAttribute('data-zcc-zip-orig-opacity');
        b.removeAttribute('data-zcc-zip-orig-cursor');
      });
    } catch(e) {}
  }

  // Lock immediately and after delays (Shopify Buy Now and dynamic buttons render late)
  applyLock();
  setTimeout(applyLock, 500);
  setTimeout(applyLock, 1500);
  setTimeout(applyLock, 3000);

  // MutationObserver: catch dynamically injected payment buttons
  if (typeof MutationObserver !== 'undefined') {
    var zipLockObserver = new MutationObserver(function() { applyLock(); });
    var watchTarget = document.querySelector('.product-form, [data-product-form], form[action*="/cart/add"]') || document.body;
    zipLockObserver.observe(watchTarget, { childList: true, subtree: true });
    // Stop observing once ZIP is verified or after 30s to avoid memory leaks
    setTimeout(function() { zipLockObserver.disconnect(); }, 30000);

    // Listen for successful ZIP validation to unlock
    window.addEventListener('zcc:validated', function handler(e) {
      var detail = (e as CustomEvent).detail;
      if (detail && detail.valid === true) {
        removeLock();
        zipLockObserver.disconnect();
        window.removeEventListener('zcc:validated', handler);
      }
    });
  } else {
    // Fallback: poll sessionStorage if MutationObserver unavailable
    window.addEventListener('zcc:validated', function handler(e) {
      var detail = (e as CustomEvent).detail;
      if (detail && detail.valid === true) {
        removeLock();
        window.removeEventListener('zcc:validated', handler);
      }
    });
  }
}

